glsl3.vert:
precision highp float;
uniform CCGlobal {
  vec4 cc_time;

  vec4 cc_screenSize;

  vec4 cc_screenScale;

  vec4 cc_nativeSize;

  mat4 cc_matView;
  mat4 cc_matViewInv;
  mat4 cc_matProj;
  mat4 cc_matProjInv;
  mat4 cc_matViewProj;
  mat4 cc_matViewProjInv;
  vec4 cc_cameraPos;

  vec4 cc_exposure;

  vec4 cc_mainLitDir;

  vec4 cc_mainLitColor;

  vec4 cc_ambientSky;
  vec4 cc_ambientGround;
};
uniform CCLocal {
  mat4 cc_matWorld;
  mat4 cc_matWorldIT;
};

in vec3 a_position;
in vec4 a_color;
out vec4 v_color;

#if USE_TEXTURE
in vec2 a_uv0;
out vec2 v_uv0;
in float a_isFront;
out float v_isFront;
#endif

void main () {
  vec4 pos = vec4(a_position, 1);

  #if CC_USE_MODEL
  pos = cc_matViewProj * cc_matWorld * pos;
  #else
  pos = cc_matViewProj * pos;
  #endif

  #if USE_TEXTURE
  v_uv0 = a_uv0;
  #endif

  v_color = a_color;
  v_isFront = a_isFront;
  gl_Position = pos;
}

glsl3.frag:
precision highp float;

#if USE_ALPHA_TEST

  uniform ALPHA_TEST {
    float alphaThreshold;
  }
#endif

void ALPHA_TEST (in vec4 color) {
  #if USE_ALPHA_TEST
      if (color.a < alphaThreshold) discard;
  #endif
}

void ALPHA_TEST (in float alpha) {
  #if USE_ALPHA_TEST
      if (alpha < alphaThreshold) discard;
  #endif
}

in vec4 v_color;

#if USE_TEXTURE
in vec2 v_uv0;
in float v_isFront;
uniform sampler2D texture0;
uniform sampler2D texture1;
#endif

uniform PROPERTIES {
  vec4 uvRange0;
  vec4 uvRange1;
  vec2 meta0;
  vec2 meta1;
}

vec2 convertUV(vec2 uv, vec4 range) {
  float x = uv.x * range[1] + range[0];
  float y = uv.y * range[3] + range[2];
  return vec2(x, y);
}

vec4 sample(sampler2D tex, vec2 uv, vec4 uvRange, vec2 meta) {
  if (meta.y == 1.0) {

    uv.y = 1.0 - uv.y;
  }
  return texture(tex, convertUV(uv, uvRange));
}

void main () {
  vec4 o = vec4(1, 1, 1, 1);

  #if USE_TEXTURE
  if(v_isFront == 1.0) {
    o *= sample(texture0, v_uv0, uvRange0, meta0);
  } else {
    o *= sample(texture1, v_uv0, uvRange1, meta1);
  }
  #endif

  o *= v_color;
  ALPHA_TEST(o);
  #if CC_USE_ALPHA_ATLAS_TEXTURE
    o.a *= texture2D(texture, v_uv0 + vec2(0, 0.5)).r;
  #endif
  gl_FragColor = o;
}

